47	const App = () => (
48	  <QueryClientProvider client={queryClient}>
49	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
50	      <AuthProvider>
51	        <TooltipProvider>
52	          <Sonner />
53	          <BrowserRouter>
54	            <SeoHead />
55	            <MaintenanceGate>
56	              <Suspense fallback={<PageLoader />}>
57	                <Routes>
58	                  <Route path="/auth" element={<Auth />} />
59	                  <Route path="/" element={<RootRoute />} />
60	                  <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
61	                  <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
62	                  <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
63	                  <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
64	                  <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
65	                  <Route path="/book-demo" element={<BookDemo />} />
66	                  <Route path="/request-feature" element={<RequestFeature />} />
67	                  <Route path="/changelog" element={<Changelog />} />
68	                  <Route path="/payment/callback" element={<PaymentCallback />} />
69	                  <Route path="*" element={<NotFound />} />
70	                </Routes>
71	              </Suspense>
72	            </MaintenanceGate>
73	            <ChatWidget />
74	          </BrowserRouter>
75	        </TooltipProvider>
76	      </AuthProvider>
77	    </ThemeProvider>
78	  </QueryClientProvider>
79	);
80	
81	export default App;
