15	const AuthContext = createContext<AuthContextType>({
16	  user: null,
17	  session: null,
18	  loading: true,
19	  isAdmin: false,
20	  profile: null,
21	  signOut: async () => {},
22	  refreshProfile: async () => {},
23	});
