import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { toast } from "sonner";
import {
  Download,
  ExternalLink,
  Users,
  Loader2,
  FileText,
} from "lucide-react";

type ApplicationStatus = "pending" | "reviewed" | "shortlisted" | "rejected";

interface Application {
  id: string;
  job_id: string;
  name: string;
  email: string;
  phone: string | null;
  linkedin_url: string | null;
  resume_path: string | null;
  resume_filename: string | null;
  status: ApplicationStatus;
  created_at: string;
}

const STATUS_LABELS: Record<ApplicationStatus, string> = {
  pending: "Pending",
  reviewed: "Reviewed",
  shortlisted: "Shortlisted",
  rejected: "Rejected",
};

const STATUS_COLORS: Record<ApplicationStatus, string> = {
  pending: "bg-muted text-muted-foreground",
  reviewed: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
  shortlisted:
    "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400",
  rejected:
    "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
};

interface ApplicationsTabProps {
  jobId: string;
}

export default function ApplicationsTab({ jobId }: ApplicationsTabProps) {
  const queryClient = useQueryClient();
  const [updatingId, setUpdatingId] = useState<string | null>(null);

  const {
    data: applications,
    isLoading,
    error,
  } = useQuery<Application[]>({
    queryKey: ["applications", jobId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("applications")
        .select(
          "id, job_id, name, email, phone, linkedin_url, resume_path, resume_filename, status, created_at"
        )
        .eq("job_id", jobId)
        .order("created_at", { ascending: false });
      if (error) throw new Error(error.message);
      return (data ?? []) as Application[];
    },
    enabled: !!jobId,
    staleTime: 30_000,
  });

  const updateStatus = useMutation({
    mutationFn: async ({
      applicationId,
      newStatus,
    }: {
      applicationId: string;
      newStatus: ApplicationStatus;
    }) => {
      const { error } = await supabase
        .from("applications")
        .update({ status: newStatus })
        .eq("id", applicationId);
      if (error) throw new Error(error.message);
    },
    onMutate: ({ applicationId }) => setUpdatingId(applicationId),
    onSuccess: (_, { applicationId, newStatus }) => {
      queryClient.setQueryData<Application[]>(
        ["applications", jobId],
        (prev) =>
          (prev ?? []).map((a) =>
            a.id === applicationId ? { ...a, status: newStatus } : a
          )
      );
      toast.success(`Application marked as ${STATUS_LABELS[newStatus]}`);
    },
    onError: (err: Error) => toast.error(err.message || "Failed to update status"),
    onSettled: () => setUpdatingId(null),
  });

  const downloadResume = async (resumePath: string, filename: string) => {
    const { data, error } = await supabase.storage
      .from("resumes")
      .download(resumePath);
    if (error || !data) {
      toast.error("Failed to download resume");
      return;
    }
    const url = URL.createObjectURL(data);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  };

  const formatDate = (iso: string) =>
    new Date(iso).toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    });

  if (isLoading) {
    return (
      <div className="space-y-3">
        {[0, 1, 2, 3].map((i) => (
          <Skeleton key={i} className="h-12 w-full rounded-md" />
        ))}
      </div>
    );
  }

  if (error) {
    return (
      <div className="rounded-lg border border-destructive/30 bg-destructive/5 p-4 text-sm text-destructive">
        Failed to load applications. Please refresh the page.
      </div>
    );
  }

  if (!applications || applications.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 space-y-4">
        <div className="rounded-xl bg-muted/50 p-4">
          <Users className="h-8 w-8 text-muted-foreground/50" />
        </div>
        <div className="text-center space-y-1">
          <h3 className="text-sm font-medium">No applications yet</h3>
          <p className="text-sm text-muted-foreground max-w-xs">
            Share your apply link to start receiving applications from candidates.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <p className="text-sm text-muted-foreground">
          {applications.length} application{applications.length !== 1 ? "s" : ""}
        </p>
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          {(["pending", "reviewed", "shortlisted", "rejected"] as const).map((s) => {
            const count = applications.filter((a) => a.status === s).length;
            if (count === 0) return null;
            return (
              <span
                key={s}
                className={`px-2 py-0.5 rounded-full text-[11px] font-medium ${STATUS_COLORS[s]}`}
              >
                {count} {STATUS_LABELS[s]}
              </span>
            );
          })}
        </div>
      </div>

      <div className="rounded-md border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <Table>
            <TableHeader className="bg-muted/40">
              <TableRow>
                <TableHead className="pl-4">Candidate</TableHead>
                <TableHead>Contact</TableHead>
                <TableHead>Resume</TableHead>
                <TableHead className="w-36">Status</TableHead>
                <TableHead className="w-28 text-right pr-4">Submitted</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {applications.map((app) => (
                <TableRow key={app.id} className="align-middle">
                  {/* Name + LinkedIn */}
                  <TableCell className="pl-4 py-3">
                    <div className="space-y-0.5">
                      <p className="text-sm font-medium leading-tight">
                        {app.name}
                      </p>
                      {app.linkedin_url && (
                        <a
                          href={app.linkedin_url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="inline-flex items-center gap-1 text-xs text-primary hover:text-primary/80 transition-colors"
                        >
                          <ExternalLink className="h-3 w-3" />
                          LinkedIn
                        </a>
                      )}
                    </div>
                  </TableCell>

                  {/* Email + Phone */}
                  <TableCell className="py-3">
                    <div className="space-y-0.5">
                      <p className="text-xs text-muted-foreground truncate max-w-[180px]">
                        {app.email}
                      </p>
                      {app.phone && (
                        <p className="text-xs text-muted-foreground">
                          {app.phone}
                        </p>
                      )}
                    </div>
                  </TableCell>

                  {/* Resume download */}
                  <TableCell className="py-3">
                    {app.resume_path && app.resume_filename ? (
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-7 gap-1.5 text-xs px-2"
                        onClick={() =>
                          downloadResume(app.resume_path!, app.resume_filename!)
                        }
                        title={`Download ${app.resume_filename}`}
                      >
                        <Download className="h-3.5 w-3.5" />
                        {app.resume_filename.length > 20
                          ? app.resume_filename.slice(0, 18) + "…"
                          : app.resume_filename}
                      </Button>
                    ) : (
                      <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
                        <FileText className="h-3.5 w-3.5" />
                        No file
                      </span>
                    )}
                  </TableCell>

                  {/* Status select */}
                  <TableCell className="py-3">
                    <div className="relative">
                      {updatingId === app.id && (
                        <Loader2 className="absolute -left-5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 animate-spin text-primary" />
                      )}
                      <Select
                        value={app.status}
                        onValueChange={(val) =>
                          updateStatus.mutate({
                            applicationId: app.id,
                            newStatus: val as ApplicationStatus,
                          })
                        }
                        disabled={updatingId === app.id}
                      >
                        <SelectTrigger className="h-7 text-xs w-32">
                          <SelectValue>
                            <span
                              className={`px-1.5 py-0.5 rounded text-[11px] font-medium ${STATUS_COLORS[app.status]}`}
                            >
                              {STATUS_LABELS[app.status]}
                            </span>
                          </SelectValue>
                        </SelectTrigger>
                        <SelectContent>
                          {(
                            ["pending", "reviewed", "shortlisted", "rejected"] as const
                          ).map((s) => (
                            <SelectItem key={s} value={s} className="text-xs">
                              <span
                                className={`px-1.5 py-0.5 rounded text-[11px] font-medium ${STATUS_COLORS[s]}`}
                              >
                                {STATUS_LABELS[s]}
                              </span>
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  </TableCell>

                  {/* Date */}
                  <TableCell className="text-right text-xs text-muted-foreground pr-4 py-3">
                    {formatDate(app.created_at)}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      </div>
    </div>
  );
}

